CREATE INDEX CONCURRENTLY IF NOT EXISTS {{index_name}}
  ON {{table_name}} USING GIST ({{tenant_column}}, {{range_column}});

-- Bookings that overlap a given window
EXPLAIN ANALYZE
SELECT *
FROM {{table_name}}
WHERE {{tenant_column}} = $1
  AND {{range_column}} && tstzrange($2, $3, '[)');

